# owner: platform
"""Seat a roster in rows, sorted by last name."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student


def _sort_key(item: Student) -> Tuple[str, str]:
    last = item.last_name.casefold()
    return (last, item.first_name.casefold())


def _sorted_roster(
    students: Iterable[Student]
) -> List[Student]:
    roster = list(students)
    if not roster:
        raise ValueError("no students to seat")
    return sorted(roster, key=_sort_key)


def _chunks(
    roster: List[Student], per_row: int
) -> List[List[Student]]:
    starts = range(0, len(roster), per_row)
    return [
        roster[start : start + per_row] for start in starts
    ]


def _format_row(number: int, chunk: List[Student]) -> str:
    names = " | ".join(item.display_name for item in chunk)
    return f"Row {number}: {names}"


def _label_rows(chunks: List[List[Student]]) -> List[str]:
    lines = []
    for number, chunk in enumerate(chunks, start=1):
        lines.append(_format_row(number, chunk))
    return lines


# ---
def seating_rows(
    students: Iterable[Student], per_row: int
) -> List[str]:
    """One line of text per seating row, by last name."""
    if per_row <= 0:
        raise ValueError("seat count must be positive")
    chunks = _chunks(_sorted_roster(students), per_row)
    return _label_rows(chunks)

