# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def _student(last_name, first_name):
    return Student("0", last_name, first_name, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            _student("Varrow", "Ines"),
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet"),
            _student("Quillon", "Sefa"),
            _student("Thistle", "Bram")
        ]

    def test_sorts_by_last_name_and_fills_rows(self):
        lines = seating_rows(self.roster, 2)
        self.assertEqual(
            lines,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Sefa | Thistle, Bram",
                "Row 3: Varrow, Ines"
            ]
        )

    def test_one_row_when_seats_cover_everyone(self):
        lines = seating_rows(self.roster, 10)
        self.assertEqual(len(lines), 1)
        self.assertEqual(lines[0].count("|"), 4)

    def test_first_name_breaks_ties(self):
        roster = [
            _student("Lee", "Zoe"),
            _student("Lee", "Ana")
        ]
        lines = seating_rows(roster, 2)
        self.assertEqual(
            lines, ["Row 1: Lee, Ana | Lee, Zoe"]
        )

    def test_last_name_order_ignores_case(self):
        roster = [
            _student("Baker", "Cy"),
            _student("abbott", "Di")
        ]
        lines = seating_rows(roster, 1)
        self.assertEqual(lines[0], "Row 1: abbott, Di")
        self.assertEqual(lines[1], "Row 2: Baker, Cy")

    def test_input_list_is_not_reordered(self):
        before = [item.last_name for item in self.roster]
        seating_rows(self.roster, 2)
        self.assertEqual(
            [item.last_name for item in self.roster], before
        )

    def test_zero_seats_per_row_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, 0)

    def test_negative_seats_per_row_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
